  while (left < right) {
    const sum = nums[left] + nums[right]
    if (sum === target) return true
    if (sum < target) left++   // need bigger number
    if (sum > target) right--  // need smaller number
  }

  return false
}

// Count character frequency
function charCount(str: string): Record<string, number> {
  const count: Record<string, number> = {}

  for (const char of str) {
    count[char] = (count[char] || 0) + 1
  }

  return count
}

charCount("hello")
// { h: 1, e: 1, l: 2, o: 1 }

// Find first non-repeating character
function firstUnique(str: string): string {
  const count = charCount(str)

  for (const char of str) {
    if (count[char] === 1) return char
  }

  return ""
}

function binarySearch(nums: number[], target: number): number {
  let left = 0
  let right = nums.length - 1

  while (left <= right) {
    const mid = Math.floor((left + right) / 2)
    if (nums[mid] === target) return mid
    if (nums[mid] < target) left = mid + 1   // search right half
    else right = mid - 1                     // search left half
  }

  return -1  // not found
}

binarySearch([1, 3, 5, 7, 9, 11], 7)  // 3

function factorial(n: number): number {
  if (n <= 1) return 1          // base case
  return n * factorial(n - 1)   // recursive case
}

factorial(5)  // 5 * 4 * 3 * 2 * 1 = 120

