// Classic stack problem: balanced brackets
function isBalanced(s: string) {
  const pairs: Record<string, string> = { ")": "(", "]": "[", "}": "{" }
  const st: string[] = []
  for (const ch of s) {
    if ("([{".includes(ch)) st.push(ch)
    else if (pairs[ch] && st.pop() !== pairs[ch]) return false
  }
  return st.length === 0
}

